the change that has to be made is just an alteration of a single line in a single function. save this as a .js file, add it to your project as a plugin, and load it after the mog hud plugin.
Code:
Battle_Hud.prototype.create_face = function() {
    if (String(Moghunter.bhud_face_visible) != "true") {return};
    this.removeChild(this._face);
    if (!this._battler) {return}; 
    this._face = new Sprite(ImageManager.loadBHud("Face_"+this._battler.actorId() +"-"+ this._battler.currentClass().id));
    this._face.anchor.x = 0.5;
    this._face.anchor.y = 0.5;
    this._face_data = [0,0,false,false,false,-1];
    this._face.ph = 0;
    this._face.animation = [-1,0,0,0,0,0,0,0,0];
    this._face.breathEffect = this._battler._bhud.faceBreath;
    this._face.scaleY = 0;
    if (String(Moghunter.bhud_face_shake) === "true") {this._face_data[2] = true}
    if (String(Moghunter.bhud_face_animated) === "true") {this._face_data[4] = true}
    this._battler._bhud_face_data = [0,0,0,1]
    this.addChild(this._face);
};
with that change, you want your files set up so that theyre named Face_[actor id]-[class id]
so Face_1-2, Face_3-5, etc

