    var img = ImageManager.loadPicture("Actor_" + this._actor.actorId() + "-" +this._actor.currentClass().id())
    this._spriteActor = new Sprite(img);
    this._spriteActor.opacity = 0;
    this._spriteActor.anchor.x = 0.5;
    this.addChild(this._spriteActor);
};
and itll be Actor_[actorId]-[classId] within the pictures folder. if you really wanted to, you could probably use the same bhud files you already have set up by using the bhud function and replacing the "Actor_" with "Face_"

